11	// View rend l'interface : header, ligne de titre, viewport, footer (Rule 124).
12	// Un overlay ouvert remplace le tout.
13	func (a *App) View() string {
14		if overlay := a.activeOverlay(); overlay != "" {
15			return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
16				lipgloss.WithWhitespaceBackground(theme.ColorBackground))
17		}
18	
19		inner := a.renderHeader() + "\n" + a.renderTitleLine() + "\n" + a.renderBody()
20		if footer := a.renderViewFooter(); footer != "" {
21			inner += "\n" + footer
22		}
23	
24		return lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
25			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
26	}
