41	// renderBody fills the viewport with the active view's content, padded to the
42	// full inner width so no line shows the terminal's own background (Rule 115).
43	func (a *App) renderBody() string {
44		content := "View not found: " + string(a.currentView)
45		if view, ok := a.views[a.currentView]; ok {
46			content = view.View()
47		}
48	
49		innerWidth := a.viewport.Width - 2 // -2 pour les bordures
50		if a.frameless() {
51			innerWidth = a.viewport.Width
52		}
53		a.viewport.SetContent(lipgloss.NewStyle().
54			Background(theme.ColorBackground).
55			Foreground(theme.ColorText).
56			Width(innerWidth).
57			Render(content))
58	
59		body := a.viewport.View()
60	
61		// Rule 136: with a filter bar below it, the viewport's bottom corners become
62		// T-junctions so the two form one closed rectangle.
63		if view, ok := a.views[a.currentView]; ok {
64			if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
65				body = replaceViewportBottomCorners(body)
66			}
67		}
68		return body
69	}
