98	// renderViewFooter returns the active view's footer, or "" when it has none.
99	func (a *App) renderViewFooter() string {
100		if view, ok := a.views[a.currentView]; ok {
101			if fv, ok := view.(FooterView); ok {
102				return fv.RenderFooter(a.width)
103			}
104		}
105		return ""
106	}
107	
108	// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
109	// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
110	// the border into one closed rectangle instead of two stacked boxes.
111	func replaceViewportBottomCorners(body string) string {
112		lastNewline := strings.LastIndex(body, "\n")
113		if lastNewline == -1 {
114			return body
115		}
116		lastLine := body[lastNewline+1:]
117		lastLine = strings.Replace(lastLine, "└", "├", 1)
118		lastLine = strings.Replace(lastLine, "┘", "┤", 1)
119		return body[:lastNewline+1] + lastLine
120	}
