// Footer message colors, one per level (Rule 128).
//
// Aliases assigned in ApplyTheme, like the syntax colours above: no theme
// file gains a key, and the three follow whatever palette is applied.
//
// They point at the **severity** colours rather than at ColorError/ColorWarn.
// The default theme makes each pair identical, so the choice is invisible
// today; it stops being invisible in a theme that separates them, and the
// intent is that a footer error reads like a CRITICAL finding and a warning
// like a MEDIUM one — same alphabet everywhere in the application.
//
// Info is deliberately ColorText, the application's ordinary text colour:
// ColorHighlight carried it before and is a yellow one notch from the
// warning's orange, which made the two levels indistinguishable.
ColorFooterInfo  lipgloss.Color
ColorFooterWarn  lipgloss.Color
ColorFooterError lipgloss.Color

// Severity colors (background + foreground pairs)
ColorSeverityCritical   lipgloss.Color

ColorSeverityInfo = applyColor(t.SeverityInfo, ColorSeverityInfo)
ColorSeverityInfoFg = applyColor(t.SeverityInfoFg, ColorText)

// Footer message colours (Rule 128). Assigned after the severity block
// because they alias it — the intent is that a footer error reads like a
// CRITICAL finding and a warning like a MEDIUM one.
ColorFooterInfo = ColorText
ColorFooterWarn = ColorSeverityMedium
ColorFooterError = ColorSeverityCritical

// Rafraîchir les styles qui dépendent des couleurs
RefreshStyles()

	StatusWarningStyle = lipgloss.NewStyle().
				Background(ColorBackground).
				Foreground(ColorWarn).
				Bold(true)
)

// Footer message styles, one per level (Rule 128).
//
// Info is not bold, the other two are: the hierarchy runs through weight as
// well as hue, and a neutral notice rendered bold would read as an alert again
// — which is what the yellow ColorHighlight line did before.
//
// Nothing outside components.FooterMessage should use these. They exist as
// exported styles so a theme change refreshes them like every other style, not
// so a view can render its own footer line.
var (
	FooterInfoStyle = lipgloss.NewStyle().
			Background(ColorBackground).
			Foreground(ColorFooterInfo).
			Bold(false)

	FooterWarnStyle = lipgloss.NewStyle().
			Background(ColorBackground).
			Foreground(ColorFooterWarn).
			Bold(true)

	FooterErrorStyle = lipgloss.NewStyle().
				Background(ColorBackground).
				Foreground(ColorFooterError).
				Bold(true)
)

